const g="/assets/cover-OM4uVkw4.webp",n="/assets/Hmw-2sisV38O.webp",t="/assets/Crazy%208s%20Sketches-KaYt0BcM.webp",c="/assets/Idea%20Documentation-cFsZ34Ie.webp",m="/assets/Prioritization%20Matrix-a4vUEzvs.webp",s="/assets/User%20Flow-BP14Jl9u.webp",r="/assets/Eksplorasi-CZexjAXP.webp",e="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question-B8LIv9Fa.webp",a="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(1%20Upgrade)-DQC-Vrt7.webp",o="/assets/specs1-CDDGgskr.webp",u="/assets/specs2-C0ZDYSul.webp",p="/assets/specs3-CT1Ub56w.webp",l="/assets/QA-C4agIGv3.webp",d="/assets/Eksplorasi%20-%20Flitter%20On-CvxZp38d.webp",k="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(2%20User%20Information)-2uSGeVLD.webp",I="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(3%20Midtrans%20Payment)-DWWqZdVL.webp",h="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(4%20Payment%20Sucess)-xIU8pVb4.webp",y={title:"NEON UJI – Subscription-Based Question Bank",title_en:"NEON UJI – Subscription-Based Question Bank",slug:"neon-uji",isActive:!0,statusBadge:"Real Case Study",statusBadge_en:"Real Case Study",roles:["Product Designer"],roles_en:["Product Designer"],timeline:"1 Week",timeline_en:"1 Week",platform:"Web Application",platform_en:"Web Application",context:"PT Vortex Buana Edumedia · Apprenticeship",context_en:"PT Vortex Buana Edumedia · Apprenticeship",organization:"PT Vortex Buana Edumedia",designTool:"Figma",techTags:["Product Design","Figma","UI/UX Design","Subscription System","Task Flow"],imageSrc:g,gallery:[g],projectUrl:"",description:"Merancang pengalaman akses Bank Soal berdasarkan tingkatan paket langganan Free, Personal, dan Business.",description_en:"Designing a subscription-based access experience for an educational question bank across Free, Personal, and Business tiers.",longDescription:`NEON UJI merupakan platform edukasi yang menyediakan fitur Bank Soal untuk mendukung kebutuhan evaluasi pembelajaran.

Dalam proyek ini, saya berperan sebagai <strong>Product Designer</strong> untuk merancang sistem pengkategorian dan pembatasan akses koleksi soal berdasarkan paket Free, Personal, dan Business. Fokus desain mencakup kejelasan hak akses, identifikasi konten premium, limited preview, serta alur upgrade paket.`,longDescription_en:`NEON UJI is an educational platform featuring a Question Bank to support learning assessment activities.

As <strong>Product Designer</strong>, I designed a tiered access experience across Free, Personal, and Business subscription tiers — focusing on access clarity, premium content visibility, limited previews, and a seamless upgrade journey.`,sections:[{id:"overview",navTitle:"Overview",navTitle_en:"Overview",title:"Project Overview",title_en:"Project Overview",subtitle:"Merancang sistem akses Bank Soal berdasarkan tingkatan paket langganan.",subtitle_en:"Designing a subscription-based access system for an educational question bank.",blocks:[{type:"text",lead:!0,content:"NEON UJI merupakan platform edukasi dengan fitur Bank Soal untuk mendukung evaluasi pembelajaran. Sebagai <strong>Product Designer</strong>, saya merancang pengalaman akses koleksi soal berbasis paket langganan Free, Personal, dan Business guna memperjelas batasan konten serta mempermudah alur upgrade.",content_en:"NEON UJI is an educational platform with a Question Bank feature supporting learning assessments. As a <strong>Product Designer</strong>, I designed a tiered access experience across Free, Personal, and Business subscriptions to clarify content availability and provide a structured upgrade path."},{type:"features_grid",title:"Project Scope",title_en:"Project Scope",features:[{title:"Subscription-Based Access",desc:"Sistem pembatasan akses koleksi soal berdasarkan tingkatan paket."},{title:"Question Bank Categorization",desc:"Pengelompokan dan diferensiasi visual kartu koleksi soal."},{title:"Premium Content Indicator",desc:"Indikator visual dan badge penanda konten berbayar."},{title:"Limited Preview",desc:"Teaser maksimal dua soal untuk koleksi yang berada di luar paket aktif."},{title:"Subscription Upgrade Flow",desc:"Alur antarmuka penawaran paket hingga konfirmasi checkout."}],features_en:[{title:"Subscription-Based Access",desc:"Access gating system based on subscription tier entitlements."},{title:"Question Bank Categorization",desc:"Grouping and visual distinction of question collection cards."},{title:"Premium Content Indicators",desc:"Visual badges and cues identifying gated premium material."},{title:"Limited Content Preview",desc:"Teaser of up to two questions for collections outside current tier."},{title:"Subscription Upgrade Flow",desc:"User journey from tier selection modal to checkout confirmation."}]},{type:"data_list",title:"My Contribution",title_en:"My Contribution",items:["Requirement Analysis — Mengidentifikasi kebutuhan produk bersama Product Manager.","HMW & Ideation — Merumuskan 9 alternatif HMW dan sketsa Crazy 8s.","Prioritization Matrix — Memetakan solusi berdasarkan dampak dan kompleksitas implementasi.","Task Flow & Interaction — Menyusun alur akses authorized, restricted, dan alur upgrade.","High-Fidelity UI Design — Merancang antarmuka menggunakan komponen Design System NEON UJI.","Design Specification & QA — Menyusun anotasi developer handoff dan memvalidasi implementasi."],items_en:["Requirement Analysis — Clarifying product requirements alongside the Product Manager.","HMW & Ideation — Framing 9 HMW questions and generating Crazy 8s sketches.","Prioritization Matrix — Mapping solutions based on impact and implementation complexity.","Task Flow & Interaction — Defining user journeys for authorized, restricted, and upgrade states.","High-Fidelity UI Design — Crafting screens using NEON UJI's existing component library.","Design Specification & QA — Creating developer handoff annotations and conducting QA checks."]}]},{id:"background",navTitle:"Background & Context",navTitle_en:"Background & Context",title:"Background & Context",title_en:"Background & Context",subtitle:"Kondisi awal Bank Soal dan alasan diperlukannya pembedaan hak akses paket langganan.",subtitle_en:"Initial state of the Question Bank and why subscription-based access was required.",blocks:[{type:"text",content:"Bank Soal di NEON UJI menyediakan kumpulan soal terstruktur untuk kebutuhan evaluasi pembelajaran. Pengguna memanfaatkan fitur ini untuk menemukan materi ujian sesuai tingkatan kelas atau topik yang dibutuhkan.",content_en:"The Question Bank in NEON UJI provides structured assessment material for teachers and learners. Users rely on this feature to discover relevant exam questions organized by subject and difficulty."},{type:"callout",tone:"neutral",title:"Existing Condition",title_en:"Existing Condition",content:"Sebelum pengembangan fitur ini, seluruh koleksi Bank Soal dapat dibuka tanpa pembatasan paket langganan. Tidak terdapat pembeda visual antara materi standar dan konten eksklusif, sehingga pengguna tidak memiliki informasi mengenai nilai lebih dari paket berbayar.",content_en:"Before this feature, all Question Bank collections were accessible without plan restrictions. There were no visual cues separating standard from premium content, leaving users unaware of the added value offered by paid subscriptions."},{type:"features_grid",title:"Why It Matters",title_en:"Why It Matters",features:[{title:"Access Clarity",desc:"Memperjelas koleksi yang dapat langsung digunakan sesuai paket aktif pengguna."},{title:"Subscription Visibility",desc:"Menampilkan transparansi hak akses antar paket secara konsisten."},{title:"Upgrade Awareness",desc:"Memberi panduan kontekstual saat pengguna memerlukan materi tingkat lanjut."}],features_en:[{title:"Access Clarity",desc:"Clarifying which collections can be used immediately under the user's current plan."},{title:"Subscription Visibility",desc:"Displaying transparent entitlement differences across subscription tiers."},{title:"Upgrade Awareness",desc:"Providing contextual guidance when users encounter higher-tier content."}]},{type:"table",title:"Scope Hak Akses Paket Langganan",title_en:"Subscription Tier Access Scope",headers:["Tingkatan Paket","Cakupan Akses Koleksi"],headers_en:["Subscription Tier","Collection Access Scope"],rows:[["Free","Akses terbatas pada koleksi bertanda Free."],["Personal","Akses ke seluruh koleksi Free dan Personal."],["Business","Akses penuh ke seluruh koleksi, termasuk paket Business."]],rows_en:[["Free","Limited access to Free-badged collections only."],["Personal","Full access to both Free and Personal collections."],["Business","Unrestricted access to all collections, including Business tier."]]}]},{id:"problem",navTitle:"Problem Definition",navTitle_en:"Problem Definition",title:"Problem Definition",title_en:"Problem Definition",subtitle:"Mengidentifikasi kendala akses pengguna dan merumuskan fokus desain melalui How Might We.",subtitle_en:"Identifying user access friction and framing the core design challenge through How Might We.",blocks:[{type:"text",content:"Ketiadaan pembeda akses membuat pengguna kesulitan mengetahui materi mana yang langsung dapat digunakan dan materi mana yang memerlukan paket langganan lebih tinggi. Tantangan perancangan adalah menghadirkan sistem pembatasan akses yang informatif tanpa menghambat eksplorasi materi.",content_en:"The absence of access differentiation made it difficult for users to know which questions were immediately usable and which required higher tiers. The core design challenge was to introduce clear access restrictions without creating friction in content discovery."},{type:"callout",tone:"neutral",title:"How Might We Exploration",title_en:"How Might We Exploration",content:"Berdasarkan arahan kebutuhan Product Manager, saya merumuskan sembilan alternatif pertanyaan How Might We (HMW) yang mencakup aspek kejelasan akses, visibilitas paket, nilai eksklusif konten, serta kemudahan proses upgrade.",content_en:"Based on requirements from the Product Manager, I formulated nine alternative How Might We (HMW) questions covering access clarity, tier visibility, premium value communication, and frictionless upgrades."},{type:"section_gallery",preview:n,previewCaption:"Dokumentasi Eksplorasi 9 Pertanyaan How Might We (HMW)",previewCaption_en:"Documentation of 9 How Might We (HMW) Exploration Questions",gallery:[{src:n,caption:"Eksplorasi 9 Pertanyaan HMW Berdasarkan Kebutuhan Fitur"}],gallery_en:[{src:n,caption:"Nine HMW Questions Framed Around Product Requirements"}]},{type:"callout",tone:"highlight",title:"Selected HMW",title_en:"Selected HMW",content:'<strong>Bagaimana kita bisa membantu pengguna mengetahui Bank Soal mana yang dapat mereka akses sesuai paketnya?</strong><br><span class="text-xs text-neutral-400 mt-2 block">Pertanyaan ini dipilih sebagai fokus utama eksplorasi solusi untuk memperjelas hak akses pengguna terhadap setiap koleksi soal.</span>',content_en:'<strong>How might we help users identify which Question Bank collections they can access based on their subscription plan?</strong><br><span class="text-xs text-neutral-400 mt-2 block">This question was selected as the primary focus for exploring design solutions that clarify user access rights.</span>'}]},{id:"exploration",navTitle:"Design Exploration",navTitle_en:"Design Exploration",title:"Requirement Analysis & Design Exploration",title_en:"Requirement Analysis & Design Exploration",subtitle:"Eksplorasi sketsa Crazy 8s, dokumentasi ide fitur, dan pemetaan prioritas dampak versus usaha.",subtitle_en:"Crazy 8s ideation, feature documentation, and impact vs. effort prioritization mapping.",blocks:[{type:"text",content:"Setelah menetapkan HMW utama, proses berlanjut ke tahap eksplorasi konsep visual dan interaksi secara terstruktur melalui sketsa cepat, pengelompokan ide, hingga matriks evaluasi.",content_en:"Following the selection of the primary HMW, the exploration progressed through rapid concept sketching, structured idea grouping, and objective evaluation matrices."},{type:"section_gallery",preview:t,previewCaption:"Dokumentasi Sketsa Crazy 8s, Idea Notes, dan Prioritization Matrix",previewCaption_en:"Documentation of Crazy 8s Sketches, Idea Notes, and Prioritization Matrix",gallery:[{src:t,caption:"01. Crazy 8s — Eksplorasi 8 Alternatif Konsep Layout & Kartu Soal"},{src:c,caption:"02. Idea Documentation — Penguraian Fungsi Fitur Menggunakan Sticky Notes"},{src:m,caption:"03. Prioritization Matrix — Pemetaan Potensi Dampak vs. Kompleksitas Usaha"}],gallery_en:[{src:t,caption:"01. Crazy 8s — Eight Rapid Layout & Card Concept Sketches"},{src:c,caption:"02. Idea Documentation — Feature Detail Mapping Using Sticky Notes"},{src:m,caption:"03. Prioritization Matrix — Impact vs. Effort Prioritization Quad"}]},{type:"features_grid",title:"Enam Solusi Desain Terpilih",title_en:"Six Selected Design Solutions",features:[{title:"1. Card Differentiation",desc:"Gaya border dan aksen visual untuk membedakan tingkatan paket koleksi."},{title:"2. Contextual Action Buttons",desc:"Tombol aksi yang otomatis berubah label dan fungsi sesuai status kepemilikan akses."},{title:"3. Subscription Badge",desc:"Label penanda kategori paket (Free, Personal, Business) pada setiap kartu."},{title:"4. Lock Access Indicator",desc:"Ikon gembok yang menandakan materi memerlukan tingkatan paket lebih tinggi."},{title:"5. Limited Preview Mechanism",desc:"Menampilkan dua butir soal pertama secara jelas dan menyamarkan sisa butir soal."},{title:"6. Package Filter Tab",desc:"Filter cepat untuk menampilkan koleksi yang cocok dengan tingkatan paket tertentu."}],features_en:[{title:"1. Card Differentiation",desc:"Border styling and visual accents to distinguish collection tiers."},{title:"2. Contextual Action Buttons",desc:"Action buttons dynamically adapting their label and state based on access rights."},{title:"3. Subscription Badge",desc:"Clear tier badges (Free, Personal, Business) pinned to each collection card."},{title:"4. Lock Access Indicator",desc:"Lock icon communicating that content requires an upgraded subscription tier."},{title:"5. Limited Preview Mechanism",desc:"Displaying the first two sample questions clearly while blurring the remainder."},{title:"6. Package Filter Tab",desc:"Convenient tab filters allowing users to view collections available under specific tiers."}]}]},{id:"task-flow",navTitle:"Task Flow & Interaction",navTitle_en:"Task Flow & Interaction",title:"Task Flow & Interaction Design",title_en:"Task Flow & Interaction Design",subtitle:"Memetakan alur pengguna dalam menemukan koleksi, verifikasi hak akses, dan proses upgrade.",subtitle_en:"Mapping user journeys across collection discovery, access verification, and upgrade flows.",blocks:[{type:"text",content:"User Flow disusun untuk memetakan perjalanan pengguna dalam dua skenario utama: pengguna dengan hak akses penuh (*Authorized Access*) dan pengguna yang memilih upgrade untuk membuka materi terkunci (*Restricted Access*).",content_en:"The User Flow maps the user experience across two main branches: users with full permissions (*Authorized Access*) and users encountering gated collections who proceed to upgrade (*Restricted Access*)."},{type:"section_gallery",preview:s,previewCaption:"Diagram User Flow: Skenario Authorized Access, Restricted Access, dan Alur Upgrade",previewCaption_en:"User Flow Diagram: Authorized Access, Restricted Access, and Upgrade Flow",gallery:[{src:s,caption:"Diagram Lengkap User Flow Fitur Bank Soal Berlangganan"}],gallery_en:[{src:s,caption:"Complete User Flow Diagram for Subscription-Based Question Bank"}]},{type:"diagram",title:"Empat Fase Alur Perjalanan Pengguna",title_en:"Four User Journey Phases",steps:[{title:"01. Menemukan Koleksi Soal",desc:"Pengguna mengakses Bank Soal pada menu Explore, mencari materi, dan memfilter berdasarkan paket."},{title:"02. Verifikasi Hak Akses",desc:"Sistem memeriksa kepemilikan paket: menampilkan akses penuh atau menampilkan status terbatas."},{title:"03. Eksplorasi Limited Preview",desc:"Pengguna dapat membaca 2 contoh soal, sementara konten terkunci diberi visual blur dan petunjuk paket."},{title:"04. Alur Upgrade Langganan",desc:"Pengguna memilih paket, melanjutkan pembayaran, dan akses dirancang untuk diperbarui setelah pembayaran terverifikasi."}],steps_en:[{title:"01. Question Discovery",desc:"Users open Explore, navigate to Question Bank, search topics, and apply tier filters."},{title:"02. Access Verification",desc:"System checks active subscription: granting direct access or presenting restricted preview."},{title:"03. Limited Preview Teaser",desc:"Users preview 2 sample questions; restricted items are blurred with clear plan requirements."},{title:"04. Subscription Upgrade",desc:"Users select a plan, proceed to checkout, and access is designed to update once payment is verified."}]},{type:"features_grid",title:"Perbandingan Kondisi Akses",title_en:"Access State Comparison",features:[{title:"Authorized Access (Akses Terbuka)",desc:`• Detail dan seluruh butir soal dapat dilihat langsung.
• Tombol tindakan menampilkan "Lihat Soal" dan "Gunakan Soal".
• Koleksi dapat langsung dimasukkan ke agenda pembelajaran.`},{title:"Restricted Access (Akses Terkunci)",desc:`• Kartu koleksi dilengkapi lock indicator dan badge paket.
• Preview dibatasi maksimal 2 soal dengan efek blur.
• Tombol tindakan utama mengarahkan ke modal "Upgrade Paket".`}],features_en:[{title:"Authorized Access",desc:`• Full collection details and all question items are accessible.
• Action buttons display "View Questions" and "Use Questions".
• Questions can be added directly to active assessments.`},{title:"Restricted Access",desc:`• Collection cards prominently feature lock indicators and tier badges.
• Preview is capped at 2 questions with blurred remainder.
• Primary CTA guides users directly to the "Upgrade Plan" modal.`}]}]},{id:"hifi-design",navTitle:"High-Fidelity UI",navTitle_en:"High-Fidelity UI",title:"High-Fidelity UI Design",title_en:"High-Fidelity UI Design",subtitle:"Penerapan solusi desain ke antarmuka Bank Soal dengan memanfaatkan komponen Design System yang ada.",subtitle_en:"Translating design decisions into Question Bank interfaces utilizing existing Design System components.",blocks:[{type:"text",content:"Pada tahap High-Fidelity, seluruh solusi visual diwujudkan ke dalam antarmuka web NEON UJI. Perancangan mengutamakan konsistensi dengan menggunakan library komponen yang telah tersedia untuk meminimalkan beban pembuatan komponen baru.",content_en:"In the High-Fidelity phase, all visual solutions were brought to life within NEON UJI's web application. The design strictly adhered to existing design system components to maintain visual consistency and avoid unnecessary engineering overhead."},{type:"section_gallery",preview:r,previewCaption:"Dokumentasi UI: Daftar Koleksi, Detail Limited Preview, dan Modal Upgrade",previewCaption_en:"UI Documentation: Collection Listing, Limited Preview Detail, and Upgrade Modal",gallery:[{src:r,caption:"01. Daftar Koleksi Bank Soal — Diferensiasi Kartu, Badge Paket, dan Tab Filter"},{src:e,caption:"02. Detail Soal & Limited Preview — Efek Blur pada Soal Terkunci dan Informasi Paket"},{src:a,caption:"03. Interaksi Upgrade — Modal Penjelasan Nilai Paket dan Call-to-Action Upgrade"}],gallery_en:[{src:r,caption:"01. Question Bank Collection Listing — Card Differentiation, Badges, and Tier Filter Tabs"},{src:e,caption:"02. Question Detail & Limited Preview — Blurred Restricted Content and Tier Notification"},{src:a,caption:"03. Upgrade Interaction — Plan Upsell Modal Explaining Tier Benefits with Primary CTA"}]},{type:"diagram",title:"Fokus Perancangan Tiga Layar Utama",title_en:"Three Core Screen Focus Areas",steps:[{title:"01. Halaman Koleksi (Listing)",desc:"Pembeda border pada kartu soal, badge paket langganan, lock icon, serta filter kategori paket."},{title:"02. Halaman Detail & Preview",desc:"Informasi rangkuman koleksi, pratinjau 2 soal pertama, efek blur pada soal ke-3 dst, dan notifikasi paket."},{title:"03. Modal Interaksi Upgrade",desc:"Rincian manfaat paket yang dituju, perbandingan harga, dan tombol aksi terarah menuju pembayaran."}],steps_en:[{title:"01. Collection Listing Screen",desc:"Distinct card borders, subscription badges, lock icons, and fast tier-based filter tabs."},{title:"02. Detail & Limited Preview Screen",desc:"Collection summary, clear view of 2 sample questions, blurred restricted items, and tier alerts."},{title:"03. Upgrade Interaction Modal",desc:"Clear summary of targeted tier benefits, pricing breakdown, and focused checkout CTA."}]}]},{id:"handoff",navTitle:"Design Specification",navTitle_en:"Design Specification",title:"Design Specification & Developer Handoff",title_en:"Design Specification & Developer Handoff",subtitle:"Dokumentasi aturan komponen, kondisi hak akses, dan perilaku interaksi menggunakan anotasi Figma.",subtitle_en:"Documenting component rules, access conditions, and interaction states via Figma annotations.",blocks:[{type:"text",content:"Untuk memastikan hasil implementasi akurat, saya mendokumentasikan aturan desain melalui anotasi visual langsung pada lembar kerja Figma. Anotasi ini berfokus pada tiga aspek teknis utama: *component behavior* (perilaku kartu dan modal), *access conditions* (kondisi hak akses tiap paket), serta *interaction requirements* (respons tombol dan alur transisi).",content_en:"To support accurate engineering implementation, I documented design rules using visual annotations directly on Figma artboards. These annotations focused on three technical aspects: component behavior (card and modal layout states), access conditions (entitlements per tier), and interaction requirements (button logic and modal transitions)."},{type:"section_gallery",preview:o,previewCaption:"Dokumentasi Spesifikasi: Aturan Sorting, Spesifikasi Modal, dan Aturan Pratinjau",previewCaption_en:"Specification Documentation: Sorting Logic, Modal Specs, and Preview Rules",gallery:[{src:o,caption:"01. Aturan Tampilan & Sorting — Prioritas Urutan Koleksi Berdasarkan Paket Pengguna"},{src:u,caption:"02. Spesifikasi Modal Upgrade — Logika Tampilan Personal vs. Business Upsell"},{src:p,caption:"03. Aturan Akses & Preview — Batasan Maksimal 2 Soal dan Penanganan Konten Terkunci"}],gallery_en:[{src:o,caption:"01. Collection Display & Sorting Rules — Prioritizing Collections Matching Active Plan"},{src:u,caption:"02. Upgrade Modal Specifications — Trigger Logic for Personal vs. Business Upsell"},{src:p,caption:"03. Access & Preview Rules — Two-Question Ceiling and Restricted Blur Handling"}]},{type:"diagram",title:"Fungsi Spesifikasi pada Tiga Area Kunci",title_en:"Specification Functions Across Three Areas",steps:[{title:"01. Collection & Sorting Rules",desc:"Menjelaskan aturan pengurutan koleksi agar materi yang sesuai dengan paket pengguna tampil di urutan atas."},{title:"02. Upgrade Modal Behavior",desc:"Mendefinisikan kondisi pemanggilan modal: klik paket Personal memicu Personal Upsell, klik paket Business memicu Business Upsell."},{title:"03. Preview & Access Boundaries",desc:"Menetapkan batasan teknis: sistem hanya memuat 2 butir soal pertama dan menyembunyikan payload butir soal berikutnya."}],steps_en:[{title:"01. Collection & Sorting Rules",desc:"Specifies sorting order ensuring collections matching user's active plan are prioritized at the top."},{title:"02. Upgrade Modal Behavior",desc:"Defines modal trigger logic: selecting Personal triggers Personal Upsell, selecting Business triggers Business Upsell."},{title:"03. Preview & Access Boundaries",desc:"Sets technical boundaries: rendering only the first 2 questions and omitting remaining question payloads."}]}]},{id:"qa-validation",navTitle:"Design QA & Validation",navTitle_en:"Design QA & Validation",title:"Design QA & Validation",title_en:"Design QA & Validation",subtitle:"Verifikasi kepatuhan hasil implementasi terhadap desain Figma dan standar kualitas antarmuka.",subtitle_en:"Verifying implementation compliance against Figma designs and interface quality standards.",blocks:[{type:"text",content:"Setelah tahap handoff, saya melakukan Design QA menggunakan checklist terstruktur untuk memeriksa hasil implementasi developer terhadap rancangan Figma. Pemeriksaan mencakup aspek visual, aksesibilitas kontras, respons antarmuka, serta penanganan berbagai kondisi konten.",content_en:"Following handoff, I conducted a structured Design QA review to audit developer implementation against the approved Figma designs. The audit evaluated visual fidelity, contrast accessibility, component states, and content edge cases."},{type:"features_grid",title:"Tiga Area Fokus Pemeriksaan QA",title_en:"Three QA Audit Categories",features:[{title:"01. Visual Consistency & UI Review",desc:"Kesesuaian komponen, margin, padding, ikon, tipografi, serta palet warna antarmuka."},{title:"02. Behavior & Accessibility",desc:"Status interaktif (hover, active, focus, disabled), rasio kontras warna, dan adaptasi breakpoint."},{title:"03. Content & Interface States",desc:"Kejelasan teks, format pesan peringatan, penanganan placeholder, dan validasi form modal."}],features_en:[{title:"01. Visual Consistency & UI Review",desc:"Component fidelity, margins, padding, iconography, typography hierarchy, and color palettes."},{title:"02. Behavior & Accessibility",desc:"Interactive states (hover, active, focus, disabled), color contrast ratios, and breakpoint responsiveness."},{title:"03. Content & Interface States",desc:"Copywriting clarity, alert messaging, empty/placeholder states, and modal validation behavior."}]},{type:"section_gallery",preview:l,previewCaption:"Dokumentasi Checklist Design QA — 11 Item Pemeriksaan Berstatus Passed",previewCaption_en:"Design QA Checklist Documentation — 11 Verification Checks Marked as Passed",gallery:[{src:l,caption:"Dokumentasi Lembar Checklist Design QA Terverifikasi"}],gallery_en:[{src:l,caption:"Verified Design QA Checklist Documentation"}]},{type:"callout",tone:"highlight",title:"Hasil Pemeriksaan QA Checklist",title_en:"QA Checklist Audit Result",content:"Berdasarkan lembar checklist Design QA yang didokumentasikan, seluruh <strong>11 item pemeriksaan memiliki status Passed</strong>. Hal ini memvalidasi bahwa seluruh kriteria penerimaan antarmuka yang diuji telah sesuai dengan spesifikasi desain.",content_en:"According to the documented Design QA checklist, all <strong>11 verification items achieved a Passed status</strong>. This validated that all tested interface criteria complied with design specifications."},{type:"callout",tone:"neutral",content:"<em>Catatan: Hasil di atas mencerminkan item checklist inspeksi antarmuka yang terdokumentasi, bukan pengujian kegunaan eksternal (usability testing) maupun metrik analitik bisnis.</em>",content_en:"<em>Note: The result above reflects documented UI inspection checklist items, not external usability testing or measured business analytics.</em>"}]},{id:"final-solution",navTitle:"Final Solution & Learnings",navTitle_en:"Final Solution & Learnings",title:"Final Solution & Learnings",title_en:"Final Solution & Learnings",subtitle:"Rangkuman empat solusi desain utama, showcase antarmuka akhir, dan refleksi pembelajaran.",subtitle_en:"Summary of four core design solutions, final interface showcase, and retrospective learnings.",blocks:[{type:"text",content:"Rancangan akhir menghadirkan pengalaman Bank Soal terstruktur yang memadukan kejelasan informasi hak akses dengan alur upgrade yang kontekstual. Dokumentasi ini mencakup hasil perancangan UI serta eksplorasi alur transaksi Midtrans sebagai panduan produk.",content_en:"The final design delivers a structured Question Bank experience that pairs transparent access clarity with contextual upgrade pathways. This documentation covers the UI deliverables and Midtrans checkout interaction exploration."},{type:"features_grid",title:"Empat Pilar Solusi Desain",title_en:"Four Core Design Pillars",features:[{title:"01. Subscription Categorization",desc:"Koleksi soal dikelompokkan secara jelas berdasarkan tier Free, Personal, dan Business."},{title:"02. Clear Access Indicators",desc:"Badge status dan ikon gembok memperjelas materi yang dapat dibuka vs. materi berbayar."},{title:"03. Limited Content Preview",desc:"Mekanisme teaser 2 butir soal memungkinkan pengguna mengevaluasi kualitas sebelum berlangganan."},{title:"04. Contextual Upgrade Flow",desc:"Rancangan alur modal upgrade terarah yang menampilkan informasi harga dan opsi pembayaran."}],features_en:[{title:"01. Subscription Categorization",desc:"Question collections clearly organized by Free, Personal, and Business subscription tiers."},{title:"02. Clear Access Indicators",desc:"Status badges and lock indicators clarify accessible versus restricted material."},{title:"03. Limited Content Preview",desc:"Two-question teaser allows users to evaluate content quality before subscribing."},{title:"04. Contextual Upgrade Flow",desc:"Targeted upgrade modal design presenting tier benefits, pricing, and checkout options."}]},{type:"section_gallery",preview:d,previewCaption:"Showcase Antarmuka Akhir: Halaman Bank Soal dan Rancangan Alur Transaksi Upgrade",previewCaption_en:"Final Interface Showcase: Question Bank Screen and Designed Upgrade Checkout Flow",gallery:[{src:d,caption:"Antarmuka Akhir Bank Soal — Tampilan Filter Paket dan Daftar Koleksi"},{src:e,caption:"Antarmuka Detail Soal — Penerapan Limited Preview dan Konten Terkunci"},{src:a,caption:"Rancangan Alur Upgrade — Langkah 1: Modal Penawaran Paket Langganan"},{src:k,caption:"Rancangan Alur Upgrade — Langkah 2: Formulir Konfirmasi Data Pengguna"},{src:I,caption:"Rancangan Alur Upgrade — Langkah 3: Antarmuka Gateway Pembayaran Midtrans"},{src:h,caption:"Rancangan Alur Upgrade — Langkah 4: Status Pembayaran Berhasil & Pembaruan Hak Akses"}],gallery_en:[{src:d,caption:"Final Question Bank Interface — Tier Filter Tabs and Collection Cards"},{src:e,caption:"Question Detail Interface — Limited Preview and Restricted Content State"},{src:a,caption:"Designed Upgrade Flow — Step 1: Subscription Tier Offer Modal"},{src:k,caption:"Designed Upgrade Flow — Step 2: User Information Confirmation Form"},{src:I,caption:"Designed Upgrade Flow — Step 3: Midtrans Payment Gateway Interface"},{src:h,caption:"Designed Upgrade Flow — Step 4: Payment Success State & Entitlement Update"}]},{type:"data_list",title:"Pembelajaran Utama (Key Learnings)",title_en:"Key Learnings",items:["Problem Framing — Menerjemahkan kebutuhan bisnis ke dalam rumusan masalah desain yang spesifik dan berpusat pada pengguna.","Design Exploration — Mengeksplorasi berbagai alternatif sebelum menetapkan solusi membantu menemukan pendekatan yang paling efektif.","Interaction Scenarios — Merancang secara komprehensif untuk berbagai kondisi hak akses mencegah celah pengalaman pengguna.","Developer Collaboration — Spesifikasi beranotasi kontekstual mempercepat pemahaman teknis dan meminimalkan revisi implementasi."],items_en:["Problem Framing — Translating product objectives into specific, user-centered design problem statements.","Design Exploration — Exploring diverse concepts before committing to a solution ensures more effective outcomes.","Interaction Scenarios — Designing thoroughly for varied access permissions prevents edge-case user friction.","Developer Collaboration — Contextual annotated specs streamline engineering handoff and reduce implementation rework."]}]},{id:"acknowledgements",navTitle:"Acknowledgements",navTitle_en:"Acknowledgements",title:"Acknowledgements",title_en:"Acknowledgements",subtitle:"Apresiasi kepada pihak yang telah membimbing dan memberi kesempatan selama proyek.",subtitle_en:"Gratitude and recognition to mentors and organization for support and collaboration.",blocks:[{type:"callout",tone:"highlight",content:`Saya mengucapkan terima kasih kepada mentor yang telah memberikan arahan, bimbingan, dan masukan selama proses pengerjaan proyek ini.

Terima kasih juga kepada <strong>PT Vortex Buana Edumedia</strong> atas kesempatan, kepercayaan, dan pengalaman yang diberikan untuk belajar serta berkontribusi langsung dalam pengembangan produk digital.

Pengalaman ini menjadi bagian berharga dalam perjalanan saya untuk terus berkembang sebagai <strong>Product Designer</strong>.`,content_en:`I would like to express my sincere gratitude to my mentor for the guidance, support, and valuable feedback throughout this project.

I am also grateful to <strong>PT Vortex Buana Edumedia</strong> for the opportunity, trust, and experience to learn and contribute directly to the development of a digital product.

This experience has been a valuable part of my journey in growing as a <strong>Product Designer</strong>.`}]}]},f="data:image/svg+xml;base64,",C={title:"NEON Design System – Standarisasi Komponen & Token",title_en:"NEON Design System – Component Library & Design Tokens",slug:"neon-design-system",isActive:!0,statusBadge:"Design System",statusBadge_en:"Design System",roles:["Design System Lead","UI Designer"],roles_en:["Design System Lead","UI Designer"],description:"Sistem desain terpadu untuk platform NEON UJI: standarisasi token warna, skala tipografi, library komponen interaktif, dokumentasi spesifikasi, dan panduan developer handoff.",description_en:"A unified design system for the NEON UJI platform: design tokens, typography hierarchy, reusable interactive component library, documentation, and handoff guidelines.",longDescription:"NEON Design System dibangun untuk memastikan konsistensi visual, efisiensi kerja tim lintas disiplin, dan kecepatan implementasi frontend pada produk NEON UJI (PT Vortex Buana Edumedia). Mencakup arsitektur token (warna netral dan semantik, spasi 4px-grid, radius, elevasi bayangan), komponen atomik hingga organisme (Buttons, Input Fields, Badges, Modals, Data Tables), serta aturan accessibility (kontras rasio WCAG). Dilengkapi dokumentasi spesifikasi interaksi, states (default, hover, focus, disabled, error), dan checklist Design QA.",longDescription_en:"NEON Design System was architected to guarantee visual consistency, cross-functional velocity, and streamlined frontend delivery across the NEON UJI ecosystem at PT Vortex Buana Edumedia. Encompasses design token architecture (semantic color systems, 4px grid spacing, radius scales, surface elevations), atomic-to-organism components (Buttons, Form Controls, Overlays, Navigation Rails), alongside WCAG accessibility compliance and comprehensive interaction state guidelines.",imageSrc:f,techTags:["Design System","Figma","UI Components","Design Tokens","Design QA"],timeline:"Jul 2026 – Okt 2026",timeline_en:"Jul 2026 – Oct 2026",platform:"Cross-Platform System (Web & Mobile)",platform_en:"Cross-Platform System (Web & Mobile)",context:"PT Vortex Buana Edumedia · Apprenticeship",context_en:"PT Vortex Buana Edumedia · Apprenticeship",projectUrl:""},i="/assets/cover-BjXXcBUM.webp",A={title:"Vitacal App – Aplikasi Kesehatan (Beta Test)",title_en:"Vitacal App – Health & Nutrition Tracker (Beta Test)",slug:"vitacal-app-aplikasi-kesehatan",statusBadge:"Beta Test",statusBadge_en:"Beta Test",roles:["UI/UX Designer","Frontend Developer","Backend Developer"],roles_en:["UI/UX Designer","Frontend Developer","Backend Developer"],isActive:!0,gallery:[i,i,i],description:"Aplikasi mobile penghitung kalori dan analisis nutrisi personal menggunakan algoritma Mifflin-St Jeor, terintegrasi Open Food Facts API dan dataset Kaggle.",description_en:"A mobile app for daily calorie calculation and personal nutritional analysis using the Mifflin-St Jeor algorithm, integrated with Open Food Facts API and Kaggle datasets.",longDescription:"Vitacal App adalah aplikasi mobile kesehatan yang membantu pengguna memahami kebutuhan kalori harian mereka secara lebih akurat dan personal. Aplikasi ini menggunakan algoritma Mifflin-St Jeor untuk menghitung BMR, BMI, serta memberikan rekomendasi dan analisis kalori berdasarkan data pribadi pengguna. Proyek ini dikembangkan mulai dari riset UI/UX di Figma, hingga implementasi Frontend menggunakan Flutter dan Backend dengan Flask serta PostgreSQL. Untuk memperkaya fungsionalitas, data pencarian makanan diambil dari dataset publik Kaggle, dan fitur pemindai barcode makanan diintegrasikan langsung dengan Open Food Facts API. Sistem autentikasi menggunakan OTP via Fonnte API untuk akses yang cepat. Fokus utama proyek ini adalah menghadirkan alat pemantau nutrisi yang kompleks secara data teknis, namun tetap memiliki antarmuka yang sangat sederhana digunakan.",imageSrc:i,techTags:["Flutter","Flask","PostgreSQL","Mifflin Algorithm","Open Food Facts API","Kaggle Dataset","Fonnte API","Figma"],timeline:"2025 - 2026",platform:"Mobile Application",platform_en:"Mobile Application",context:"Final Academic Project / Tugas Akhir",context_en:"Final Academic Project / Graduation Thesis",theChallenge:"Memahami asupan kalori harian dan menjaga berat badan ideal merupakan tantangan bagi banyak orang. Sayangnya, banyak aplikasi pencatat kalori di pasaran memiliki antarmuka yang terlalu rumit dan database makanan yang terbatas. Pengguna sering kali merasa kesulitan dan kehilangan motivasi saat harus memasukkan data makanan kemasan yang mereka konsumsi sehari-hari secara manual.",theChallenge_en:"Understanding daily calorie intake and maintaining an ideal weight is a challenge for many. Unfortunately, many calorie tracking apps on the market have interfaces that are too complex and food databases that are too limited. Users often struggle and lose motivation when they have to manually log packaged foods they consume daily.",theSolution:"Pendekatan Vitacal App berfokus pada personalisasi pengguna dan kemudahan input data. Mengandalkan algoritma <strong>Mifflin-St Jeor</strong> yang teruji klinis, aplikasi membagi sistem menjadi Frontend Flutter yang responsif dan Backend Flask. Untuk mengatasi hambatan pencatatan, sistem menarik data dari dataset publik Kaggle untuk pencarian makanan lokal, dan mengintegrasikan Open Food Facts API agar pengguna cukup melakukan scan barcode pada makanan kemasan tanpa harus mengetik manual.",theSolution_en:"The Vitacal App approach focuses on user personalization and ease of data entry. Relying on the clinically proven <strong>Mifflin-St Jeor</strong> algorithm, the app splits the system into a responsive Flutter frontend and a Flask backend. To address logging friction, the system pulls data from a public Kaggle dataset for local food searches, and integrates the Open Food Facts API so users can simply scan barcodes on packaged foods instead of typing manually.",keyFeatures:[{title:"Personalisasi & Analisis Kalori",desc:"Menghitung batas kalori harian, BMI, dan analisis riwayat berat badan secara personal dan presisi menggunakan algoritma Mifflin."},{title:"Smart Barcode Scanner",desc:"Integrasi dengan Open Food Facts API untuk mengenali dan melacak nutrisi makanan kemasan secara instan hanya dengan memindai barcode."},{title:"Pencarian Makanan Komprehensif",desc:"Database pencarian makanan yang kaya dan akurat, diolah langsung dari dataset nutrisi publik Kaggle."},{title:"Otentikasi OTP WhatsApp",desc:"Sistem login dan registrasi yang mulus, aman, dan tanpa password menggunakan nomor WhatsApp melalui integrasi Fonnte API."}],keyFeatures_en:[{title:"Personalization & Calorie Analysis",desc:"Calculates daily calorie limits, BMI, and analyzes weight history precisely using the Mifflin algorithm."},{title:"Smart Barcode Scanner",desc:"Integration with the Open Food Facts API to instantly identify and track packaged food nutrition by scanning barcodes."},{title:"Comprehensive Food Search",desc:"Rich and accurate food search database, processed directly from Kaggle public nutrition datasets."},{title:"WhatsApp OTP Authentication",desc:"Seamless, secure, passwordless registration and login using WhatsApp numbers integrated via Fonnte API."}],theImpact:"Aplikasi ini berhasil menghadirkan solusi pemantauan gizi yang sangat praktis. Integrasi API pihak ketiga (Kaggle & Open Food Facts) secara signifikan memangkas waktu proses logging makanan bagi pengguna, menjadikan aplikasi ini tidak sekadar prototipe teoretis, melainkan produk fungsional yang siap memecahkan masalah diet di dunia nyata.",theImpact_en:"This application successfully delivers a highly practical nutritional monitoring solution. Third-party API integrations (Kaggle & Open Food Facts) significantly reduced food logging time for users, making the app not just a theoretical prototype, but a functional product ready to solve real-world dietary challenges.",projectUrl:"https://github.com/ariyoaziz/vitacal_app"},w="/assets/cover-CxTBtQb_.webp",v={title:"FrameFlow – Solusi Proofing Foto Modern (Beta Test)",title_en:"FrameFlow – Modern Photo Proofing Solution (Beta Test)",slug:"frameflow",statusBadge:"Beta Test",statusBadge_en:"Beta Test",isActive:!0,roles:["UI/UX Designer","Frontend Developer"],roles_en:["UI/UX Designer","Frontend Developer"],description:"Platform delivery foto instan yang mengintegrasikan Google Drive dan WhatsApp untuk mempermudah klien memilih foto favorit tanpa ribet.",description_en:"An instant photo delivery platform integrating Google Drive and WhatsApp to simplify the photo selection process for clients.",longDescription:"FrameFlow adalah solusi proofing foto modern yang dirancang khusus untuk fotografer (Wedding, Portrait, Event, Commercial). Aplikasi ini mempercepat proses pengiriman foto ke klien. Cukup hubungkan Google Drive, buat galeri dalam hitungan detik, dan biarkan klien memilih foto favorit mereka secara interaktif. Hasil pilihan klien akan otomatis dikirimkan ke WhatsApp Anda, menghilangkan keribetan dan miskomunikasi dalam proses seleksi foto. Proyek ini masih dalam tahap beta test.",longDescription_en:"FrameFlow is a modern photo proofing solution designed specifically for photographers (Wedding, Portrait, Event, Commercial). This app speeds up the photo delivery process to clients. Simply connect Google Drive, create a gallery in seconds, and let clients choose their favorite photos interactively. The client's selections will automatically be sent to your WhatsApp, eliminating hassle and miscommunication in the photo selection process. This project is currently in the beta test stage.",imageSrc:w,techTags:["Frontend","Web App","UI/UX Design","Beta Test"],timeline:"2025",timeline_en:"2025",platform:"Web Application",platform_en:"Web Application",context:"Personal Project / Eksplorasi Frontend",context_en:"Personal Project / Frontend Exploration",projectUrl:"https://frameflow-navy.vercel.app/"},S="data:image/svg+xml;base64,",P={title:"Berworkshed – Digital Product & Creative Workshop",title_en:"Berworkshed – Digital Product & Creative Workshop",slug:"berworkshed",isActive:!0,isBuilding:!0,statusBadge:"Building",statusBadge_en:"Building",roles:["Founder","Product Designer","Developer"],roles_en:["Founder","Product Designer","Developer"],description:"Inisiatif studio mandiri dan bengkel kerja kreatif yang sedang dibangun untuk merancang solusi digital, produk web interaktif, dan eksplorasi desain terapan.",description_en:"An independent studio initiative and creative workshop currently being built to craft digital solutions, interactive web products, and applied design explorations.",longDescription:"Berworkshed adalah inisiatif studio mandiri dan wadah eksplorasi kreatif yang berfokus pada desain produk digital, rekayasa frontend modern, dan perancangan pengalaman pengguna yang berkarakter. Proyek ini dibangun dari nol sebagai laboratorium kerja untuk melahirkan produk-produk mandiri yang menyelesaikan kebutuhan nyata, mulai dari tool produktivitas, antarmuka web interaktif, hingga visual branding. Saat ini Berworkshed sedang dalam tahap pembangunan fondasi, standarisasi sistem komponen, dan pengembangan portofolio produk perdana.",longDescription_en:"Berworkshed is an independent studio initiative and creative workshop space focusing on digital product design, modern frontend engineering, and distinctive user experience craftsmanship. Built from the ground up as a working laboratory, it aims to create standalone products that solve real user needs—spanning productivity tools, interactive web interfaces, and visual branding. Currently in active development, focusing on component system standardization and inaugural product builds.",imageSrc:S,techTags:["Building","Product Design","Creative Studio","Frontend","UI/UX Design"],timeline:"2026 – Sekarang",timeline_en:"2026 – Present",platform:"Digital Studio / Lab",platform_en:"Digital Studio / Lab",context:"Independent Venture / Building in Public",context_en:"Independent Venture / Building in Public",projectUrl:""},b="/assets/cover-B3t3S3rK.webp",Z={title:"CV Builder",title_en:"CV Builder",slug:"cv-builder",statusBadge:"Web App",statusBadge_en:"Web App",roles:["Product Designer","Frontend Developer"],roles_en:["Product Designer","Frontend Developer"],isActive:!0,description:"CV Builder adalah aplikasi web client-side untuk membuat CV profesional yang terstruktur, ramah ATS, responsif, dan siap dicetak atau disimpan sebagai PDF langsung dari browser.",description_en:"CV Builder is a client-side web application for creating structured, ATS-friendly, responsive CVs that can be printed or saved as PDF directly from the browser.",longDescription:"CV Builder dirancang untuk membantu pengguna membuat CV profesional dengan proses yang cepat, terstruktur, dan tetap fleksibel. Aplikasi ini berjalan sepenuhnya di sisi client, sehingga pengguna dapat mengedit CV tanpa akun dan tanpa database. Editor CV menggunakan section yang terstruktur, menyediakan template Modern, Minimal, dan Classic, serta menampilkan preview real-time dengan format kertas A4. CV dapat langsung dicetak atau disimpan sebagai PDF melalui fitur bawaan browser. Pengguna juga dapat mengimpor dan mengekspor data CV dalam format JSON agar data mudah dipindahkan dan dicadangkan. Dukungan bahasa Indonesia dan Inggris, tampilan yang responsif untuk desktop, tablet, dan mobile, security headers, optimasi static assets, serta metadata Open Graph melengkapi pengalaman aplikasi. Untuk membantu penulisan, aplikasi menyediakan prompt AI eksternal yang dapat digunakan secara manual untuk membuat atau memperbaiki isi CV, kemudian hasil JSON-nya dapat diimpor kembali ke aplikasi. Seluruh data utama disimpan di browser menggunakan localStorage dan tidak dikirim ke server secara otomatis. Source code dikembangkan di repository privat CV-Builder-Raw, disanitasi melalui GitHub Actions ke repository publik CV-Builder, lalu dideploy sebagai static export Next.js dengan output folder out menggunakan Cloudflare Workers Static Assets ke website production cv-builder.weareaap.workers.dev.",longDescription_en:"CV Builder is designed to help users create professional CVs through a fast, structured, and flexible workflow. The application runs entirely on the client side, allowing users to edit their CV without an account or database. Its structured editor includes Modern, Minimal, and Classic templates, along with a real-time A4 paper preview. CVs can be printed or saved as PDF directly through the browser. Users can also import and export CV data as JSON for easy transfer and backup. Indonesian and English language support, responsive layouts for desktop, tablet, and mobile, security headers, static asset optimization, and Open Graph metadata complete the experience. For writing assistance, the app provides external AI prompts that can be used manually to create or improve CV content, after which the resulting JSON can be imported back into the application. All primary data is stored in the browser using localStorage and is not sent to a server automatically. Source code is developed in the private CV-Builder-Raw repository, sanitized through GitHub Actions into the public CV-Builder repository, then deployed as a Next.js static export with the out output folder using Cloudflare Workers Static Assets at cv-builder.weareaap.workers.dev.",keyFeatures:[{title:"Editor CV Terstruktur",desc:"Menyusun isi CV melalui section yang jelas agar informasi mudah dikelola dan tetap ramah ATS."},{title:"Tiga Template Visual",desc:"Pilih template Modern, Minimal, atau Classic sesuai kebutuhan dan karakter profesional."},{title:"Preview A4 dan PDF",desc:"Melihat perubahan secara real-time dalam format A4, lalu mencetak atau menyimpan CV sebagai PDF langsung dari browser."},{title:"Import dan Export JSON",desc:"Memindahkan, mencadangkan, dan memulihkan data CV menggunakan format JSON."},{title:"Penyimpanan Lokal",desc:"Data utama disimpan di localStorage tanpa akun dan tanpa database, sehingga tetap berada di browser pengguna."},{title:"Prompt AI Eksternal",desc:"Membantu membuat atau memperbaiki isi CV melalui layanan AI eksternal secara manual, kemudian mengimpor hasil JSON kembali ke aplikasi."},{title:"Bilingual dan Responsif",desc:"Mendukung bahasa Indonesia dan Inggris serta nyaman digunakan di desktop, tablet, dan mobile."},{title:"Static Deployment",desc:"Dibangun sebagai static export Next.js dengan output out dan dideploy melalui Cloudflare Workers Static Assets."}],keyFeatures_en:[{title:"Structured CV Editor",desc:"Organize CV content into clear sections so information stays easy to manage and ATS-friendly."},{title:"Three Visual Templates",desc:"Choose Modern, Minimal, or Classic templates based on your needs and professional style."},{title:"A4 Preview and PDF",desc:"See changes in real time on an A4 layout, then print or save the CV as PDF directly from the browser."},{title:"JSON Import and Export",desc:"Transfer, back up, and restore CV data using the JSON format."},{title:"Local Storage",desc:"Primary data is stored in localStorage without accounts or a database, keeping it in the user's browser."},{title:"External AI Prompts",desc:"Create or improve CV content through an external AI service manually, then import the resulting JSON back into the app."},{title:"Bilingual and Responsive",desc:"Supports Indonesian and English and works comfortably on desktop, tablet, and mobile."},{title:"Static Deployment",desc:"Built as a Next.js static export with an out output folder and deployed through Cloudflare Workers Static Assets."}],imageSrc:b,gallery:[b],techTags:["Frontend","Next.js","React","TypeScript","Tailwind CSS","Radix UI","Zustand","React Hook Form","Zod","Lucide React","Sonner","date-fns","GitHub Actions","Cloudflare Workers","Static Export"],timeline:"2026",timeline_en:"2026",platform:"Web Application",platform_en:"Web Application",context:"Personal Product / Portfolio Project",context_en:"Personal Product / Portfolio Project",projectUrl:"https://cv-builder.weareaap.workers.dev"},D="/assets/cover-BOdbDh29.webp",B={title:"UI/UX Redesign – Aplikasi LinkAja (Halaman Beranda)",title_en:"UI/UX Redesign – LinkAja App (Homepage)",slug:"ui-ux-redesign-aplikasi-linkaja-halaman-beranda",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Redesain halaman beranda aplikasi LinkAja dengan fokus pada penyederhanaan antarmuka dan peningkatan navigasi pengguna.",description_en:"Redesign of the LinkAja app homepage focusing on interface simplification, logical feature grouping, and improved visual accessibility. Features a modern and clean style for better mobile navigation.",imageSrc:D,techTags:["UI/UX Design","Figma","Redesign","Mobile App"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Studi Kasus UI/UX",context_en:"UI/UX Case Study",projectUrl:"https://www.figma.com/proto/IDGtCHDIcpBGVSCdmmEieC/Desain-Ulang-APP-LInkAja?page-id=5%3A57&node-id=5-60&p=f&viewport=293%2C-18%2C1.28&t=tBMct1pVLikWEzHC-1&scaling=scale-down&content-scaling=fixed",theChallenge:"Aplikasi keuangan digital seringkali dipenuhi dengan puluhan fitur dan ikon promosi di halaman berandanya, membuat pengguna baru merasa kebingungan (<em>cognitive overload</em>) saat mencoba mencari fitur utama seperti transfer atau pembayaran.",theChallenge_en:"Digital financial apps are often packed with dozens of features and promotional icons on their homepage, causing new users to experience cognitive overload when trying to find main functions like transfers or payments.",theSolution:"Melalui proses riset desain, saya merancang ulang halaman beranda LinkAja di Figma. Saya mengelompokkan ikon berdasarkan kategori prioritas, memperbesar elemen navigasi utama, serta memberikan ruang kosong (<em>white space</em>) yang cukup agar tampilan terasa lebih bersih, modern, dan minimalis.",theSolution_en:"Through a design research process, I redesigned the LinkAja homepage in Figma. I grouped icons based on priority categories, enlarged the main navigation elements, and provided sufficient white space so that the layout feels cleaner, more modern, and minimalist.",keyFeatures:[{title:"Simplified Navigation",desc:"Mengurangi kekacauan visual dengan memprioritaskan fungsi utama aplikasi."},{title:"Modern Aesthetics",desc:"Pendekatan warna dan tipografi baru yang lebih menyegarkan mata pengguna."}],keyFeatures_en:[{title:"Simplified Navigation",desc:"Reduces visual clutter by prioritizing the app's core functionalities."},{title:"Modern Aesthetics",desc:"A refreshing new color and typography approach that is easier on the user's eyes."}],theImpact:"Desain ulang ini menghasilkan prototipe visual yang jauh lebih intuitif. Studi kasus ini membuktikan bahwa penyederhanaan antarmuka dapat secara drastis meningkatkan kenyamanan pengguna tanpa harus menghilangkan fungsionalitas bisnis dari aplikasi itu sendiri.",theImpact_en:"This redesign resulted in a significantly more intuitive visual prototype. This case study demonstrates that simplifying the interface can drastically improve user comfort without eliminating the business functionalities of the app itself."},M="/assets/cover-D4MADJYd.webp",j={title:"UI/UX Design – Website E-Commerce Alat Outdoor",title_en:"UI/UX Design – Outdoor Gear E-Commerce",slug:"ui-ux-design-website-e-commerce-alat-outdoor",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Desain UI/UX untuk platform e-commerce perlengkapan outdoor dengan navigasi yang intuitif dan visual yang bersih.",description_en:"Interface design for an e-commerce platform selling outdoor gear such as tents, cooking equipment, and hiking clothes. Focuses on intuitive user experience.",imageSrc:M,techTags:["UI/UX Design","Figma","E-Commerce","Prototyping"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Latihan Eksplorasi Desain",context_en:"Design Exploration Practice",projectUrl:"https://www.figma.com/design/cQTRvW7zsCFRTWT30f5tHe/e-Com?node-id=0-1&t=kskOzYVPNCdrkweR-1",theChallenge:"Situs <em>e-commerce</em> seringkali penuh sesak dengan produk, filter, dan promosi yang membuat pengguna kebingungan mencari barang spesifik, terutama untuk produk <em>niche</em> seperti peralatan <em>outdoor</em> dan <em>hiking</em>.",theChallenge_en:"E-commerce websites are often cluttered with products, filters, and promotions that confuse users looking for specific items, especially for niche products like outdoor and hiking gear.",theSolution:"Saya memusatkan desain pada navigasi yang efisien (<em>frictionless navigation</em>). Proses penyaringan kategori (tenda, alat masak, pakaian) dibuat sangat menonjol. Saya menerapkan skema warna <em>earth-tone</em> yang selaras dengan tema alam bebas, serta memberikan ruang kosong yang luas (<em>clean UI</em>) di sekitar foto produk.",theSolution_en:"I focused the design on frictionless navigation. The category filtering process (tents, cooking gear, apparel) is highly emphasized. I applied an earth-toned color palette aligned with the outdoor theme, and provided ample white space around product photos for a clean UI.",keyFeatures:[{title:"Clean Layout",desc:"Fokus langsung pada produk berkualitas tinggi tanpa distraksi elemen berlebih."},{title:"Intuitive Filtering",desc:"Sistem filter dan pencarian yang disesuaikan dengan kebiasaan pendaki/petualang."}],keyFeatures_en:[{title:"Clean Layout",desc:"Direct focus on high-quality products without the distraction of excessive UI elements."},{title:"Intuitive Filtering",desc:"Filter and search systems customized to the habits of hikers/adventurers."}],theImpact:"Menghasilkan <em>mockup</em> UI beresolusi tinggi yang siap diserahkan (<em>hand-off</em>) kepada tim <em>frontend</em>. Desain ini membuktikan kemampuan saya merangkai antarmuka penjualan yang berorientasi pada konversi (<em>conversion-centric design</em>).",theImpact_en:"Delivered a high-fidelity UI mockup ready for hand-off to the frontend team. This design demonstrates my ability to create sales interfaces focused on conversion-centric design."},F="/assets/cover-BvjOOP68.webp",U={title:"UI/UX Design – Order Food App",title_en:"UI/UX Design – Order Food App",slug:"ui-ux-design-order-food-app",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Konsep desain aplikasi pemesanan makanan dengan tampilan modern dan alur pemesanan yang sederhana.",description_en:"Food ordering app design concept with a clean and modern approach. Provides an easily navigable user experience.",imageSrc:F,techTags:["UI/UX Design","Figma","Mobile App","Prototype"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Personal Portfolio Design",context_en:"Personal Portfolio Design",projectUrl:"https://www.behance.net/gallery/210655317/order-food",theChallenge:"Membuat aplikasi pengantaran makanan mengharuskan kita memikirkan bagaimana pengguna bisa menemukan makanan favorit, memasukkan ke keranjang, dan melakukan <em>checkout</em> dalam jumlah ketukan (<em>taps</em>) seminimal mungkin.",theChallenge_en:"Creating a food delivery app requires thinking about how users can find their favorite food, add it to the cart, and complete checkout in as few taps as possible.",theSolution:"Desain aplikasi ini memprioritaskan fotografi makanan (<em>food imagery</em>) yang besar untuk menggugah selera pengguna. Alur pemesanan dirancang secara linier (satu arah) agar tidak membingungkan, dari halaman beranda, rincian menu, modifikasi pesanan (<em>add-ons</em>), hingga layar <em>checkout</em> akhir.",theSolution_en:"The design of this application prioritizes large food imagery to stimulate the user's appetite. The order flow is designed linearly (one-way) to avoid confusion, navigating smoothly from the homepage, menu details, order customizations (add-ons), to the final checkout screen.",keyFeatures:[{title:"Appetizing Visuals",desc:"Penataan UI yang menonjolkan visual gambar menu dengan tata letak bergaya modern."},{title:"Linear Checkout Flow",desc:"Alur pembelian yang sangat ringkas untuk mempercepat proses konversi pesanan."}],keyFeatures_en:[{title:"Appetizing Visuals",desc:"UI layout highlighting menu imagery with modern layout styles."},{title:"Linear Checkout Flow",desc:"A highly simplified buying flow to speed up the order conversion process."}],theImpact:"Konsep desain ini telah dipublikasikan di Behance dan mendapatkan apresiasi positif atas pendekatan minimalisnya yang tetap mempertahankan fungsionalitas utama aplikasi pesan antar.",theImpact_en:"This design concept was published on Behance and received positive feedback for its minimalist approach while retaining the core features of a food delivery application."},T="/assets/cover-C3v7gSjj.webp",x={title:"UI/UX Design – Coffee App",title_en:"UI/UX Design – Coffee App",slug:"ui-ux-design-coffee-app",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Desain antarmuka aplikasi pemesanan kopi dengan visual elegan dan alur pengguna yang sederhana.",description_en:"An elegant and modern coffee ordering app interface design, emphasizing user comfort. Designed using Figma.",imageSrc:T,techTags:["UI/UX Design","Figma","Mobile App","Product Design"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Personal Portfolio Design",context_en:"Personal Portfolio Design",projectUrl:"https://www.behance.net/gallery/210655381/coffee",theChallenge:"Aplikasi <em>coffee shop</em> membutuhkan sentuhan personalisasi yang kuat (seperti mengatur ukuran gelas, kadar gula, jenis susu, dan es) tanpa membuat tampilan pemesanan terasa mengintimidasi atau rumit layaknya formulir panjang.",theChallenge_en:"Coffee shop applications require a strong touch of personalization (such as adjusting cup sizes, sweetness, milk types, and ice) without making the ordering screen feel intimidating or cluttered like a long form.",theSolution:"Saya memecahkan masalah ini dengan pendekatan <em>card UI</em> dan <em>toggle buttons</em>. Pengguna dapat meracik kopi mereka melalui opsi visual yang menyenangkan secara interaktif. Skema warna yang digunakan didominasi oleh corak kopi elegan dan gaya minimalis yang mewah (<em>premium feel</em>).",theSolution_en:"I solved this problem using a card UI and toggle button approach. Users can customize their drinks interactively through pleasant visual choices. The color palette is dominated by elegant coffee shades and a luxurious minimalist styling for a premium feel.",keyFeatures:[{title:"Customization Interface",desc:"Antarmuka kustomisasi minuman (gula, es, susu) yang sangat mudah digunakan."},{title:"Premium Dark Theme",desc:"Skema warna elegan yang mencerminkan suasana kedai kopi berkelas."}],keyFeatures_en:[{title:"Customization Interface",desc:"Highly intuitive drink customization interface (sugar, ice, milk) with minimal steps."},{title:"Premium Dark Theme",desc:"An elegant color scheme reflecting the atmosphere of a classy coffee shop."}],theImpact:"Desain ini (yang juga dapat dilihat di portofolio Behance saya) merepresentasikan kapabilitas saya dalam memadukan keindahan visual estetis dengan pengalaman pengguna (<em>User Experience</em>) yang logis dan fungsional.",theImpact_en:"This design (which is also showcased on my Behance portfolio) represents my capability to blend aesthetic visual beauty with a logical, functional User Experience."},W=[y,C,A,v,P,Z,B,j,U,x];export{W as a,f as b,b as c,S as d,w as f,g as n,i as v};
